import { setup } from "@zag-js/core"
import { dispatchInputValueEvent, raf } from "@zag-js/dom-query"
import { isEqual, setValueAtIndex } from "@zag-js/utils"
import * as dom from "./pin-input.dom"
import type { PinInputSchema } from "./pin-input.types"

const { choose, createMachine } = setup<PinInputSchema>()

export const machine = createMachine({
  props({ props }) {
    return {
      placeholder: "○",
      otp: false,
      type: "numeric",
      defaultValue: props.count ? fill([], props.count) : [],
      ...props,
    }
  },

  initialState() {
    return "idle"
  },

  context({ prop, bindable }) {
    return {
      value: bindable<string[]>(() => ({
        value: prop("value") ? fill(prop("value")!, prop("count")) : undefined,
        defaultValue: fill(prop("defaultValue") ?? [], prop("count")),
        isEqual,
        onChange(value) {
          prop("onValueChange")?.({ value, valueAsString: value.join("") })
        },
      })),
      focusedIndex: bindable(() => ({
        sync: true,
        defaultValue: -1,
      })),
      // TODO: Move this to `props` in next major version
      count: bindable(() => ({
        defaultValue: prop("count"),
      })),
    }
  },

  computed: {
    _value: ({ context }) => fill(context.get("value"), context.get("count")),
    valueLength: ({ computed }) => computed("_value").length,
    filledValueLength: ({ computed }) => computed("_value").filter((v) => v?.trim() !== "").length,
    isValueComplete: ({ computed }) => computed("valueLength") === computed("filledValueLength"),
    valueAsString: ({ computed }) => computed("_value").join(""),
    focusedValue: ({ computed, context }) => computed("_value")[context.get("focusedIndex")] || "",
  },

  entry: choose([
    {
      guard: "autoFocus",
      actions: ["setInputCount", "setFocusIndexToFirst"],
    },
    { actions: ["setInputCount"] },
  ]),

  watch({ action, track, context, computed }) {
    track([() => context.get("focusedIndex")], () => {
      action(["focusInput", "selectInputIfNeeded"])
    })
    track([() => context.get("value").join(",")], () => {
      action(["syncInputElements", "dispatchInputEvent"])
    })
    track([() => computed("isValueComplete")], () => {
      action(["invokeOnComplete", "blurFocusedInputIfNeeded", "autoSubmitIfNeeded"])
    })
  },

  on: {
    "VALUE.SET": [
      {
        guard: "hasIndex",
        actions: ["setValueAtIndex"],
      },
      { actions: ["setValue"] },
    ],
    "VALUE.CLEAR": {
      actions: ["clearValue", "setFocusIndexToFirst"],
    },
  },

  states: {
    idle: {
      on: {
        "INPUT.FOCUS": {
          target: "focused",
          actions: ["setFocusedIndex"],
        },
      },
    },
    focused: {
      on: {
        "INPUT.CHANGE": {
          actions: ["setFocusedValue", "syncInputValue", "advanceFocusedIndex"],
        },
        "INPUT.ADVANCE": {
          actions: ["advanceFocusedIndex"],
        },

        "INPUT.PASTE": {
          actions: ["setPastedValue", "setLastValueFocusIndex"],
        },
        "INPUT.FOCUS": {
          actions: ["setFocusedIndex", "focusInput"],
        },
        "INPUT.BLUR": {
          target: "idle",
          actions: ["clearFocusedIndex"],
        },
        "INPUT.DELETE": {
          guard: "hasValue",
          actions: ["clearFocusedValue"],
        },
        "INPUT.ARROW_LEFT": {
          actions: ["setPrevFocusedIndex"],
        },
        "INPUT.ARROW_RIGHT": {
          actions: ["setNextFocusedIndex"],
        },
        "INPUT.HOME": {
          actions: ["setFocusIndexToFirst"],
        },
        "INPUT.END": {
          actions: ["setFocusIndexToLast"],
        },
        "INPUT.BACKSPACE": [
          {
            guard: "hasValue",
            actions: ["clearFocusedValue", "setPrevFocusedIndex"],
          },
          {
            actions: ["setPrevFocusedIndex", "clearFocusedValue"],
          },
        ],
        "INPUT.ENTER": {
          guard: "isValueComplete",
          actions: ["requestFormSubmit"],
        },
        "VALUE.INVALID": {
          actions: ["invokeOnInvalid"],
        },
      },
    },
  },

  implementations: {
    guards: {
      autoFocus: ({ prop }) => !!prop("autoFocus"),
      hasValue: ({ context, computed }) => computed("_value")[context.get("focusedIndex")] !== "",
      isValueComplete: ({ computed }) => computed("isValueComplete"),
      hasIndex: ({ event }) => event.index !== undefined,
    },

    actions: {
      dispatchInputEvent({ computed, scope }) {
        const inputEl = dom.getHiddenInputEl(scope)
        dispatchInputValueEvent(inputEl, { value: computed("valueAsString") })
      },
      setInputCount({ scope, context, prop }) {
        if (prop("count")) return
        const inputEls = dom.getInputEls(scope)
        context.set("count", inputEls.length)
      },
      focusInput({ context, scope }) {
        const focusedIndex = context.get("focusedIndex")
        if (focusedIndex === -1) return
        queueMicrotask(() => {
          dom.getInputElAtIndex(scope, focusedIndex)?.focus({ preventScroll: true })
        })
      },
      selectInputIfNeeded({ context, prop, scope }) {
        const focusedIndex = context.get("focusedIndex")
        if (!prop("selectOnFocus") || focusedIndex === -1) return
        raf(() => {
          dom.getInputElAtIndex(scope, focusedIndex)?.select()
        })
      },
      invokeOnComplete({ computed, prop }) {
        if (!computed("isValueComplete")) return
        prop("onValueComplete")?.({
          value: computed("_value"),
          valueAsString: computed("valueAsString"),
        })
      },
      invokeOnInvalid({ context, event, prop }) {
        prop("onValueInvalid")?.({
          value: event.value,
          index: context.get("focusedIndex"),
        })
      },
      clearFocusedIndex({ context }) {
        context.set("focusedIndex", -1)
      },
      setFocusedIndex({ context, event, computed }) {
        const maxIndex = Math.min(computed("filledValueLength"), computed("valueLength") - 1)
        context.set("focusedIndex", Math.min(event.index, maxIndex))
      },
      setValue({ context, event }) {
        const value = fill(event.value, context.get("count"))
        context.set("value", value)
      },
      setFocusedValue({ context, event, computed, flush }) {
        const focusedValue = computed("focusedValue")
        const focusedIndex = context.get("focusedIndex")
        const value = getNextValue(focusedValue, event.value)
        flush(() => {
          context.set("value", setValueAtIndex(computed("_value"), focusedIndex, value))
        })
      },
      revertInputValue({ context, computed, scope }) {
        const inputEl = dom.getInputElAtIndex(scope, context.get("focusedIndex"))
        dom.setInputValue(inputEl, computed("focusedValue"))
      },
      syncInputValue({ context, event, scope }) {
        const value = context.get("value")
        const inputEl = dom.getInputElAtIndex(scope, event.index)
        dom.setInputValue(inputEl, value[event.index])
      },
      syncInputElements({ context, scope }) {
        const inputEls = dom.getInputEls(scope)
        const value = context.get("value")
        inputEls.forEach((inputEl, index) => {
          dom.setInputValue(inputEl, value[index])
        })
      },
      setPastedValue({ context, event, computed, flush }) {
        raf(() => {
          const valueAsString = computed("valueAsString")
          const focusedIndex = context.get("focusedIndex")
          const valueLength = computed("valueLength")
          const filledValueLength = computed("filledValueLength")

          const startIndex = Math.min(focusedIndex, filledValueLength)

          // keep value left of cursor
          // replace value from cursor to end with pasted text
          const left = startIndex > 0 ? valueAsString.substring(0, focusedIndex) : ""
          const right = event.value.substring(0, valueLength - startIndex)

          const value = fill(`${left}${right}`.split(""), valueLength)

          flush(() => {
            context.set("value", value)
          })
        })
      },
      setValueAtIndex({ context, event, computed }) {
        const nextValue = getNextValue(computed("focusedValue"), event.value)
        context.set("value", setValueAtIndex(computed("_value"), event.index, nextValue))
      },
      clearValue({ context }) {
        const nextValue = Array.from<string>({ length: context.get("count") }).fill("")
        queueMicrotask(() => {
          context.set("value", nextValue)
        })
      },
      clearFocusedValue({ context, computed }) {
        const focusedIndex = context.get("focusedIndex")
        if (focusedIndex === -1) return
        // Splice and shift remaining values left to avoid holes
        const value = [...computed("_value")]
        value.splice(focusedIndex, 1)
        value.push("")
        context.set("value", value)
      },
      setFocusIndexToFirst({ context }) {
        context.set("focusedIndex", 0)
      },
      setFocusIndexToLast({ context, computed }) {
        context.set("focusedIndex", Math.max(computed("filledValueLength") - 1, 0))
      },
      advanceFocusedIndex({ context, computed }) {
        context.set("focusedIndex", Math.min(context.get("focusedIndex") + 1, computed("valueLength") - 1))
      },
      setNextFocusedIndex({ context, computed }) {
        const nextIndex = context.get("focusedIndex") + 1
        const maxIndex = Math.min(computed("filledValueLength"), computed("valueLength") - 1)
        context.set("focusedIndex", Math.min(nextIndex, maxIndex))
      },
      setPrevFocusedIndex({ context }) {
        context.set("focusedIndex", Math.max(context.get("focusedIndex") - 1, 0))
      },
      setLastValueFocusIndex({ context, computed }) {
        raf(() => {
          context.set("focusedIndex", Math.min(computed("filledValueLength"), computed("valueLength") - 1))
        })
      },
      blurFocusedInputIfNeeded({ context, computed, prop, scope }) {
        if (!prop("blurOnComplete") || !computed("isValueComplete")) return
        raf(() => {
          dom.getInputElAtIndex(scope, context.get("focusedIndex"))?.blur()
        })
      },
      requestFormSubmit({ computed, prop, scope }) {
        if (!prop("name") || !computed("isValueComplete")) return
        const inputEl = dom.getHiddenInputEl(scope)
        inputEl?.form?.requestSubmit()
      },
      autoSubmitIfNeeded({ computed, prop, scope }) {
        if (!prop("autoSubmit") || !computed("isValueComplete")) return
        const inputEl = dom.getHiddenInputEl(scope)
        inputEl?.form?.requestSubmit()
      },
    },
  },
})

function getNextValue(current: string, next: string) {
  let nextValue = next
  if (current[0] === next[0]) {
    nextValue = next[1]
  } else if (current[0] === next[1]) {
    nextValue = next[0]
  }
  const chars = nextValue.split("")
  nextValue = chars[chars.length - 1]
  return nextValue ?? ""
}

function fill(value: string[], count: number | undefined) {
  // Guard against an undefined/zero count so we never collapse a provided value to an empty array
  const length = count || value.length
  return Array.from<string>({ length })
    .fill("")
    .map((v, i) => value[i] || v)
}

const REGEX = {
  numeric: /^[0-9]+$/,
  alphabetic: /^[A-Za-z]+$/,
  alphanumeric: /^[a-zA-Z0-9]+$/i,
}

type PinInputType = keyof typeof REGEX

export function isValidType(type: string, value: string) {
  if (!type) return true
  return !!REGEX[type as keyof typeof REGEX]?.test(value)
}

export function isValidValue(value: string, type: PinInputType, pattern?: string) {
  if (!pattern) return isValidType(type, value)
  const regex = new RegExp(pattern, "g")
  return regex.test(value)
}

import { createMachine, memo } from "@zag-js/core"
import { isValueWithinRange } from "@zag-js/utils"
import type { StepsSchema } from "./steps.types"

export const machine = createMachine<StepsSchema>({
  props({ props }) {
    return {
      defaultStep: 0,
      count: 1,
      linear: false,
      orientation: "horizontal",
      ...props,
    }
  },

  context({ prop, bindable }) {
    return {
      step: bindable<number>(() => ({
        defaultValue: prop("defaultStep"),
        value: prop("step"),
        onChange(value) {
          prop("onStepChange")?.({ step: value })
          const completed = value == prop("count")
          if (completed) prop("onStepComplete")?.()
        },
      })),
    }
  },

  computed: {
    percent: memo(
      ({ context, prop }) => [context.get("step"), prop("count")],
      ([step, count]) => (step / count) * 100,
    ),
    hasNextStep: ({ context, prop }) => context.get("step") < prop("count"),
    hasPrevStep: ({ context }) => context.get("step") > 0,
    completed: ({ context, prop }) => context.get("step") === prop("count"),
  },

  initialState() {
    return "idle"
  },

  entry: ["validateStepIndex"],

  states: {
    idle: {
      on: {
        "STEP.SET": [
          {
            guard: "isValidStepNavigation",
            actions: ["setStep"],
          },
          {
            actions: ["invokeOnStepInvalid"],
          },
        ],
        "STEP.NEXT": [
          {
            guard: "isCurrentStepValid",
            actions: ["goToNextStep"],
          },
          {
            actions: ["invokeOnStepInvalid"],
          },
        ],
        "STEP.PREV": {
          actions: ["goToPrevStep"],
        },
        "STEP.RESET": {
          actions: ["resetStep"],
        },
      },
    },
  },

  implementations: {
    guards: {
      isCurrentStepValid({ context, prop }) {
        const current = context.get("step")
        // Skippable steps bypass validation
        if (prop("isStepSkippable")?.(current)) return true
        const isStepValid = prop("isStepValid")
        if (!isStepValid) return true
        return isStepValid(current)
      },
      isValidStepNavigation({ context, event, prop }) {
        const current = context.get("step")
        // Always allow backward navigation
        if (event.value <= current) return true
        // Skippable steps bypass validation
        if (prop("isStepSkippable")?.(current)) return true
        // For forward navigation, validate current step
        const isStepValid = prop("isStepValid")
        if (!isStepValid) return true
        return isStepValid(current)
      },
    },

    actions: {
      goToNextStep({ context, prop }) {
        const count = prop("count")
        context.set("step", Math.min(context.get("step") + 1, count))
      },
      goToPrevStep({ context }) {
        context.set("step", Math.max(context.get("step") - 1, 0))
      },
      resetStep({ context }) {
        context.set("step", 0)
      },
      setStep({ context, event }) {
        context.set("step", event.value)
      },
      validateStepIndex({ context, prop }) {
        validateStepIndex(prop("count"), context.get("step"))
      },
      invokeOnStepInvalid({ context, event, prop }) {
        prop("onStepInvalid")?.({
          step: context.get("step"),
          action: event.type === "STEP.NEXT" ? "next" : "set",
          targetStep: event.value,
        })
      },
    },
  },
})

const validateStepIndex = (count: number, step: number) => {
  if (!isValueWithinRange(step, 0, count)) {
    throw new RangeError(`[zag-js/steps] step index ${step} is out of bounds`)
  }
}

import { NumberParser } from "@internationalized/number"
import type { Params } from "@zag-js/core"
import type { NumberInputSchema } from "./number-input.types"

export const createFormatter = (locale: string, options: Intl.NumberFormatOptions = {}) => {
  return new Intl.NumberFormat(locale, options)
}

export const createParser = (locale: string, options: Intl.NumberFormatOptions = {}) => {
  return new NumberParser(locale, options)
}

type Ctx = Pick<Params<NumberInputSchema>, "prop" | "computed">

export const parseValue = (value: string, params: Ctx) => {
  const { prop, computed } = params
  if (!prop("formatOptions")) return parseFloat(value)
  if (value === "") return Number.NaN
  return computed("parser").parse(value)
}

export const formatValue = (value: number, params: Ctx): string => {
  const { prop, computed } = params
  if (Number.isNaN(value)) return ""
  if (!prop("formatOptions")) return value.toString()
  return computed("formatter").format(value)
}

export const getDefaultStep = (step: number | undefined, formatOptions: Intl.NumberFormatOptions | undefined) => {
  let defaultStep = step !== undefined && !Number.isNaN(step) ? step : 1
  if (formatOptions?.style === "percent" && (step === undefined || Number.isNaN(step))) {
    defaultStep = 0.01
  }
  return defaultStep
}

import { memo, setup } from "@zag-js/core"
import {
  addDomEvent,
  isSafari,
  observeAttributes,
  raf,
  requestPointerLock,
  setElementValue,
  trackFormControl,
} from "@zag-js/dom-query"
import type { Point } from "@zag-js/types"
import {
  callAll,
  clampValue,
  decrementValue,
  incrementValue,
  isValueAtMax,
  isValueAtMin,
  isValueWithinRange,
  mergeWithDefault,
} from "@zag-js/utils"
import { recordCursor, restoreCursor } from "./cursor"
import * as dom from "./number-input.dom"
import { defaultTranslations } from "./number-input.translations"
import type { HintValue, NumberInputSchema } from "./number-input.types"
import { createFormatter, createParser, formatValue, getDefaultStep, parseValue } from "./number-input.utils"

const { choose, guards, createMachine } = setup<NumberInputSchema>()

const { not, and } = guards

export const machine = createMachine({
  props({ props }) {
    const step = getDefaultStep(props.step, props.formatOptions)
    return {
      dir: "ltr",
      locale: "en-US",
      focusInputOnChange: true,
      clampValueOnBlur: !props.allowOverflow,
      allowOverflow: false,
      inputMode: "decimal",
      pattern: "-?[0-9]*(.[0-9]+)?",
      defaultValue: "",
      step,
      min: Number.MIN_SAFE_INTEGER,
      max: Number.MAX_SAFE_INTEGER,
      spinOnPress: true,
      ...props,
      largeStep: props.largeStep ?? 10 * step,
      smallStep: props.smallStep ?? step / 10,
    }
  },

  initialState() {
    return "idle"
  },

  context({ prop, bindable, getComputed }) {
    return {
      value: bindable<string>(() => ({
        defaultValue: prop("defaultValue"),
        value: prop("value"),
        onChange(value) {
          const computed = getComputed()
          const valueAsNumber = parseValue(value, { computed, prop })
          prop("onValueChange")?.({ value, valueAsNumber })
        },
      })),
      hint: bindable<HintValue | null>(() => ({ defaultValue: null })),
      scrubberCursorPoint: bindable<Point | null>(() => ({
        defaultValue: null,
        hash(value) {
          return value ? `x:${value.x}, y:${value.y}` : ""
        },
      })),
      fieldsetDisabled: bindable<boolean>(() => ({ defaultValue: false })),
    }
  },

  computed: {
    isRtl: ({ prop }) => prop("dir") === "rtl",
    valueAsNumber: ({ context, computed, prop }) => parseValue(context.get("value"), { computed, prop }),
    formattedValue: ({ computed, prop }) => formatValue(computed("valueAsNumber"), { computed, prop }),
    isAtMin: ({ computed, prop }) => isValueAtMin(computed("valueAsNumber"), prop("min")),
    isAtMax: ({ computed, prop }) => isValueAtMax(computed("valueAsNumber"), prop("max")),
    isOutOfRange: ({ computed, prop }) => !isValueWithinRange(computed("valueAsNumber"), prop("min"), prop("max")),
    isValueEmpty: ({ context }) => context.get("value") === "",
    isDisabled: ({ prop, context }) => !!prop("disabled") || context.get("fieldsetDisabled"),
    canIncrement: ({ prop, computed }) => prop("allowOverflow") || !computed("isAtMax"),
    canDecrement: ({ prop, computed }) => prop("allowOverflow") || !computed("isAtMin"),
    valueText: ({ prop, context }) => {
      const translations = mergeWithDefault(defaultTranslations, prop("translations"))
      return translations.valueText?.(context.get("value"))
    },
    formatter: memo(
      ({ prop }) => [prop("locale"), prop("formatOptions")],
      ([locale, formatOptions]) => createFormatter(locale, formatOptions),
    ),
    parser: memo(
      ({ prop }) => [prop("locale"), prop("formatOptions")],
      ([locale, formatOptions]) => createParser(locale, formatOptions),
    ),
  },

  watch({ track, action, context, computed, prop }) {
    track([() => context.get("value"), () => prop("locale"), () => JSON.stringify(prop("formatOptions"))], () => {
      action(["syncInputElement"])
    })

    track([() => computed("isOutOfRange")], () => {
      action(["invokeOnInvalid"])
    })

    track([() => context.hash("scrubberCursorPoint")], () => {
      action(["setVirtualCursorPosition"])
    })
  },

  effects: ["trackFormControl"],

  on: {
    "VALUE.SET": {
      actions: ["setRawValue"],
    },
    "VALUE.CLEAR": {
      actions: ["clearValue"],
    },
    "VALUE.INCREMENT": {
      actions: ["increment"],
    },
    "VALUE.DECREMENT": {
      actions: ["decrement"],
    },
  },

  states: {
    idle: {
      on: {
        "TRIGGER.PRESS_DOWN": [
          { guard: "isTouchPointer", target: "before:spin", actions: ["setHint"] },
          {
            target: "before:spin",
            actions: ["focusInput", "invokeOnFocus", "setHint"],
          },
        ],
        "SCRUBBER.PRESS_DOWN": {
          target: "scrubbing",
          actions: ["focusInput", "invokeOnFocus", "setHint", "setCursorPoint"],
        },
        "INPUT.FOCUS": {
          target: "focused",
          actions: ["focusInput", "invokeOnFocus"],
        },
      },
    },

    focused: {
      tags: ["focus"],
      effects: ["attachWheelListener"],
      on: {
        "TRIGGER.PRESS_DOWN": [
          { guard: "isTouchPointer", target: "before:spin", actions: ["setHint"] },
          { target: "before:spin", actions: ["focusInput", "setHint"] },
        ],
        "SCRUBBER.PRESS_DOWN": {
          target: "scrubbing",
          actions: ["focusInput", "setHint", "setCursorPoint"],
        },
        "INPUT.ARROW_UP": {
          actions: ["increment"],
        },
        "INPUT.ARROW_DOWN": {
          actions: ["decrement"],
        },
        "INPUT.HOME": {
          actions: ["decrementToMin"],
        },
        "INPUT.END": {
          actions: ["incrementToMax"],
        },
        "INPUT.CHANGE": {
          actions: ["setValue", "setHint"],
        },
        "INPUT.BLUR": [
          {
            guard: and("clampValueOnBlur", not("isValueEmpty"), not("isInRange")),
            target: "idle",
            actions: ["setClampedValue", "clearHint", "invokeOnBlur", "invokeOnValueCommit"],
          },
          {
            guard: not("isInRange"),
            target: "idle",
            actions: ["setFormattedValue", "clearHint", "invokeOnBlur", "invokeOnInvalid", "invokeOnValueCommit"],
          },
          {
            target: "idle",
            actions: ["setFormattedValue", "clearHint", "invokeOnBlur", "invokeOnValueCommit"],
          },
        ],
        "INPUT.ENTER": {
          actions: ["setFormattedValue", "clearHint", "invokeOnBlur", "invokeOnValueCommit"],
        },
      },
    },

    "before:spin": {
      tags: ["focus"],
      effects: ["trackButtonDisabled", "waitForChangeDelay"],
      entry: choose([
        { guard: "isIncrementHint", actions: ["increment"] },
        { guard: "isDecrementHint", actions: ["decrement"] },
      ]),
      on: {
        CHANGE_DELAY: {
          target: "spinning",
          guard: and("isInRange", "spinOnPress"),
        },
        "TRIGGER.PRESS_UP": [
          { guard: "isTouchPointer", target: "focused", actions: ["clearHint"] },
          { target: "focused", actions: ["focusInput", "clearHint"] },
        ],
      },
    },

    spinning: {
      tags: ["focus"],
      effects: ["trackButtonDisabled", "spinValue"],
      on: {
        SPIN: [
          {
            guard: "isIncrementHint",
            actions: ["increment"],
          },
          {
            guard: "isDecrementHint",
            actions: ["decrement"],
          },
        ],
        "TRIGGER.PRESS_UP": {
          target: "focused",
          actions: ["focusInput", "clearHint"],
        },
      },
    },

    scrubbing: {
      tags: ["focus"],
      effects: ["activatePointerLock", "trackMousemove", "setupVirtualCursor", "preventTextSelection"],
      on: {
        "SCRUBBER.POINTER_UP": {
          target: "focused",
          actions: ["focusInput", "clearCursorPoint"],
        },
        "SCRUBBER.POINTER_MOVE": [
          {
            guard: "isIncrementHint",
            actions: ["increment", "setCursorPoint"],
          },
          {
            guard: "isDecrementHint",
            actions: ["decrement", "setCursorPoint"],
          },
        ],
      },
    },
  },

  implementations: {
    guards: {
      clampValueOnBlur: ({ prop }) => prop("clampValueOnBlur"),
      spinOnPress: ({ prop }) => !!prop("spinOnPress"),
      isInRange: ({ computed }) => !computed("isOutOfRange"),
      isValueEmpty: ({ computed }) => computed("isValueEmpty"),
      isDecrementHint: ({ context, event }) => (event.hint ?? context.get("hint")) === "decrement",
      isIncrementHint: ({ context, event }) => (event.hint ?? context.get("hint")) === "increment",
      isTouchPointer: ({ event }) => event.pointerType === "touch",
    },

    effects: {
      waitForChangeDelay({ send }) {
        const id = setTimeout(() => {
          send({ type: "CHANGE_DELAY" })
        }, 300)
        return () => clearTimeout(id)
      },

      spinValue({ send }) {
        const id = setInterval(() => {
          send({ type: "SPIN" })
        }, 50)
        return () => clearInterval(id)
      },

      trackFormControl({ context, scope }) {
        const inputEl = dom.getInputEl(scope)
        return trackFormControl(inputEl, {
          onFieldsetDisabledChange(disabled) {
            context.set("fieldsetDisabled", disabled)
          },
          onFormReset() {
            context.set("value", context.initial("value"))
          },
        })
      },
      setupVirtualCursor({ context, scope }) {
        const point = context.get("scrubberCursorPoint")
        return dom.setupVirtualCursor(scope, point)
      },
      preventTextSelection({ scope }) {
        return dom.preventTextSelection(scope)
      },
      trackButtonDisabled({ context, scope, send }) {
        const hint = context.get("hint")
        const btn = dom.getPressedTriggerEl(scope, hint)
        return observeAttributes(btn, {
          attributes: ["disabled"],
          callback() {
            send({ type: "TRIGGER.PRESS_UP", src: "attr" })
          },
        })
      },
      attachWheelListener({ scope, send, prop }) {
        const inputEl = dom.getInputEl(scope)
        if (!inputEl || !scope.isActiveElement(inputEl) || !prop("allowMouseWheel")) return

        function onWheel(event: WheelEvent) {
          event.preventDefault()
          const dir = Math.sign(event.deltaY) * -1
          if (dir === 1) {
            send({ type: "VALUE.INCREMENT" })
          } else if (dir === -1) {
            send({ type: "VALUE.DECREMENT" })
          }
        }

        return addDomEvent(inputEl, "wheel", onWheel, { passive: false })
      },
      activatePointerLock({ scope }) {
        if (isSafari()) return
        return requestPointerLock(scope.getDoc())
      },
      trackMousemove({ scope, send, context, computed }) {
        const doc = scope.getDoc()

        function onMousemove(event: MouseEvent) {
          const point = context.get("scrubberCursorPoint")
          const isRtl = computed("isRtl")
          const value = dom.getMousemoveValue(scope, { point, isRtl, event })
          if (!value.hint) return
          send({
            type: "SCRUBBER.POINTER_MOVE",
            hint: value.hint,
            point: value.point,
          })
        }

        function onMouseup() {
          send({ type: "SCRUBBER.POINTER_UP" })
        }

        return callAll(addDomEvent(doc, "mousemove", onMousemove, false), addDomEvent(doc, "mouseup", onMouseup, false))
      },
    },

    actions: {
      focusInput({ scope, prop }) {
        if (!prop("focusInputOnChange")) return
        const inputEl = dom.getInputEl(scope)
        if (scope.isActiveElement(inputEl)) return
        raf(() => inputEl?.focus({ preventScroll: true }))
